function hasChanged(layer, changed) {
  return layer.inputs.some((input) => changed.includes(input));
}

function firstChangedIndex(layers, changed) {
  return layers.findIndex((layer) => layer.inputs.some((i) => changed.includes(i)));
}

function layersFrom(names, index) {
  return index === -1 ? [] : names.slice(index);
}

function rebuildSeconds(costs, index) {
  if (index === -1) return 0;
  return costs.slice(index).reduce((sum, c) => sum + c, 0);
}

function computeRebuildPlan(layers, changed) {
  const rebuilt = [];
  let cascading = false;
  for (const layer of layers) {
    if (cascading || layer.inputs.some((i) => changed.includes(i))) {
      cascading = true;
      rebuilt.push(layer.name);
    }
  }
  return rebuilt;
}

function countCached(layers, changed) {
  let cached = 0;
  for (const layer of layers) {
    if (layer.inputs.some((i) => changed.includes(i))) break;
    cached += 1;
  }
  return cached;
}

function buildSeconds(layers, costs, changed) {
  let total = 0;
  let cascading = false;
  layers.forEach((layer, i) => {
    if (cascading || layer.inputs.some((input) => changed.includes(input))) {
      cascading = true;
      total += costs[i];
    }
  });
  return total;
}
